import { PageHeader } from '@gntik-ai/blocks';
import {
  AttachmentList,
  ChatAnnouncer,
  ChatComposer,
  ChatLayout,
  ChatMessage,
  CitationList,
  Markdown,
  SuggestionChips,
  ReasoningBlock,
  useChat,
  type ChatAdapter,
  type ChatAttachment,
  ToolCallCard,
  type ChatFeedback,
  type CitationSource,
  type Suggestion,
} from '@gntik-ai/chat';
import { SquarePen } from '@gntik-ai/icons';
import { Page, TooltipProvider, type BreadcrumbItem } from '@gntik-ai/ui';
import { Fragment, useMemo, useState } from 'react';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import {
  assistantBreadcrumbs,
  assistantReply,
  assistantSources,
  assistantSuggestions,
  assistantTool,
  createScriptedAdapter,
  type AssistantTool,
} from './data';

export interface AssistantChatProps {
  /** Experimental runtime adapter. Its URL must be the product backend; provider keys stay server-side. */
  adapter?: ChatAdapter;
  title: string;
  suggestions: Suggestion[];
  /** Sources cited under the reply and listed in the details panel. */
  sources: CitationSource[];
  /** Mock tool call run before each reply. */
  tool: AssistantTool;
  /** Mock reply (markdown), streamed in chunks. */
  reply: string;
  /** Milliseconds between streamed chunks. */
  tickMs: number;
  /** Show the details panel. */
  withPanel: boolean;
  /** Called with each prompt the user sends. */
  onSend: (text: string) => void;
  onFeedback: (feedback: ChatFeedback) => void;
  breadcrumbs: BreadcrumbItem[];
  currentHref: string;
  /** ConsoleShell props (app nav, user, workspaces, sidebar footer, topbar…). */
  shell: Omit<ConsoleShellProps, 'children'>;
}

/** Assistant chat: streams a backend adapter, or an abortable scripted demo when no adapter is supplied. */
export default function AssistantChatPage(props: Partial<AssistantChatProps>) {
  const {
    adapter,
    title = 'Assistant',
    suggestions = assistantSuggestions,
    sources = assistantSources,
    tool = assistantTool,
    reply = assistantReply,
    tickMs = 30,
    withPanel = true,
    onSend,
    onFeedback,
    breadcrumbs = assistantBreadcrumbs,
    currentHref = '/assistant',
    shell,
  } = props;
  const scripted = useMemo(() => createScriptedAdapter(reply, tool, tickMs, sources), [reply, tool, tickMs, sources]);
  const {
    messages: turns,
    isStreaming: streaming,
    sendMessage,
    stop,
    regenerate,
    setMessages,
  } = useChat({ adapter: adapter ?? scripted, flushIntervalMs: 0 });
  const [feedback, setFeedback] = useState<Record<string, ChatFeedback>>({});
  const send = (text: string, attachments: ChatAttachment[] = []) => {
    if (streaming) return;
    sendMessage(text, attachments);
    onSend?.(text);
  };
  const newConversation = () => {
    stop();
    setMessages([]);
    setFeedback({});
  };
  const lastReply = [...turns]
    .reverse()
    .find((t) => t.role === 'assistant' && t.status === 'done')
    ?.parts.filter((p) => p.type === 'text')
    .map((p) => p.text)
    .join('');

  return (
    <ConsoleShell breadcrumbs={breadcrumbs} currentHref={currentHref} {...shell}>
      <Page
        width="full"
        header={
          <PageHeader
            breadcrumbs={null}
            title={title}
            description="Ask about projects, deployments, invoices and members. Answers cite their sources."
            status=""
            meta={[]}
            tabs={null}
            actions={[
              {
                label: 'New conversation',
                icon: SquarePen,
                variant: 'secondary',
                disabled: turns.length === 0,
                onClick: newConversation,
              },
            ]}
          />
        }
      >
        <TooltipProvider>
          <div className="h-[680px] min-h-0 overflow-hidden rounded-xl border border-border">
            <ChatLayout
              header={
                <h2 className="px-4 py-3 text-[13px] font-semibold text-foreground">
                  {turns.length === 0 ? 'New conversation' : 'Conversation'}
                </h2>
              }
              panel={
                withPanel ? (
                  <div className="flex flex-col gap-4 p-4 text-[13px]">
                    <div>
                      <h2 className="font-semibold text-foreground">Details</h2>
                      <p className="mt-1 text-muted-foreground">
                        Read access to projects, deployments, invoices and members in this workspace.
                      </p>
                    </div>
                    <CitationList sources={sources} heading="Context sources" />
                  </div>
                ) : undefined
              }
              composer={<ChatComposer onSubmit={send} streaming={streaming} onStop={stop} maxLength={4000} />}
            >
              {turns.length === 0 && (
                <div className="flex flex-col gap-5 pt-10">
                  <h3 className="text-center text-[20px] font-semibold tracking-tight text-foreground">
                    How can I help?
                  </h3>
                  <SuggestionChips suggestions={suggestions} onSelect={(text) => send(text)} />
                </div>
              )}
              {turns.map((t) => {
                const text = t.parts
                  .filter((p) => p.type === 'text')
                  .map((p) => p.text)
                  .join('');
                const files = t.parts.filter((p) => p.type === 'file').map((p) => p.file);
                const citations = t.parts.filter((p) => p.type === 'source').map((p) => p.source);
                const busy = t.status === 'pending' || t.status === 'streaming';
                return (
                  <Fragment key={t.id}>
                    {t.parts
                      .filter((p) => p.type === 'tool')
                      .map((part) => (
                        <ChatMessage key={part.toolCallId} role="tool" timestamp={t.createdAt}>
                          <ToolCallCard
                            name={part.toolName}
                            status={part.status}
                            durationMs={
                              !adapter
                                ? part.status === 'succeeded'
                                  ? tool.durationMs
                                  : part.status === 'failed'
                                    ? 0
                                    : undefined
                                : undefined
                            }
                            args={part.input}
                            result={part.output}
                            error={
                              part.errorText ??
                              (!adapter && part.status === 'failed' ? 'Stopped by the user.' : undefined)
                            }
                          />
                        </ChatMessage>
                      ))}
                    <ChatMessage
                      role={t.role}
                      timestamp={t.createdAt}
                      streaming={busy}
                      copyText={t.role === 'assistant' ? text : undefined}
                      onRetry={t.role === 'assistant' && !streaming ? () => regenerate(t.id) : undefined}
                      feedback={feedback[t.id] ?? null}
                      onFeedback={
                        t.role === 'assistant'
                          ? (f) => {
                              setFeedback((previous) => ({ ...previous, [t.id]: f }));
                              onFeedback?.(f);
                            }
                          : undefined
                      }
                    >
                      {t.parts
                        .filter((p) => p.type === 'reasoning')
                        .map((part) => (
                          <ReasoningBlock key={part.id} streaming={busy && part.state === 'streaming'}>
                            {part.text}
                          </ReasoningBlock>
                        ))}
                      {text && (t.role === 'assistant' ? <Markdown streaming={busy}>{text}</Markdown> : text)}
                      {files.length > 0 && <AttachmentList attachments={files} />}
                      {citations.length > 0 && <CitationList sources={citations} className="mt-3" />}
                      {t.error && (
                        <p role="alert" className="text-destructive-text">
                          {t.error}
                        </p>
                      )}
                    </ChatMessage>
                  </Fragment>
                );
              })}
              <ChatAnnouncer streaming={streaming} lastReply={lastReply} />
            </ChatLayout>
          </div>
        </TooltipProvider>
      </Page>
    </ConsoleShell>
  );
}

import type { ChatAdapter, ChatChunk, CitationSource, Suggestion } from '@gntik-ai/chat';
import type { BreadcrumbItem } from '@gntik-ai/ui';

/** Mock tool call the assistant runs before answering. */
export interface AssistantTool {
  name: string;
  args: unknown;
  result: unknown;
  durationMs: number;
}

export const assistantSuggestions: Suggestion[] = [
  { label: 'Summarise this week’s deployments', description: 'What shipped across projects and what rolled back' },
  { label: 'Which invoices are still open?', description: 'Unpaid invoices from last month' },
  { label: 'Who has admin access?', description: 'Members with an admin role' },
  { label: 'Why did the last build fail?', description: 'Likely cause and a fix' },
];

export const assistantSources: CitationSource[] = [
  {
    title: 'Deployment history · web-app',
    url: 'https://app.example.com/projects/web-app/deployments',
    snippet: '14 deployments in the last 7 days, 1 rolled back.',
  },
  {
    title: 'Rollback guide',
    url: 'https://docs.example.com/deployments/rollback',
    snippet: 'Roll back from the Deployments page or with the CLI.',
  },
  {
    title: 'Health checks',
    url: 'https://docs.example.com/deployments/health-checks',
    snippet: 'A deployment is promoted only after every region reports healthy.',
  },
];

export const assistantTool: AssistantTool = {
  name: 'list_deployments',
  args: { project: 'web-app', since: '7d' },
  result: { count: 14, succeeded: 13, rolledBack: 1, latest: 'v3.2.0' },
  durationMs: 600,
};

export const assistantReply = `This week **web-app** shipped 14 deployments:

| Status | Count |
| --- | --- |
| Succeeded | 13 |
| Rolled back | 1 |

The rollback was \`v3.1.4\`: its health check failed in one region, so traffic stayed on the previous build.

To pin the current release from the CLI:

\`\`\`bash
deploy pin --project web-app --version v3.2.0
\`\`\`

The [rollback guide](https://docs.example.com/deployments/rollback) has the full steps.`;

export const assistantBreadcrumbs: BreadcrumbItem[] = [
  { label: 'Acme Industries', href: '/overview' },
  { label: 'Assistant' },
];

/** Splits text into small chunks to imitate token streaming. */
export function chunkReply(text: string, size = 6): string[] {
  const out: string[] = [];
  for (let i = 0; i < text.length; i += size) out.push(text.slice(i, i + size));
  return out;
}

/** Demo-only backend substitute. All chunk timers are scheduled eagerly and cleared on abort. */
export function createScriptedAdapter(
  reply: string,
  tool: AssistantTool,
  tickMs: number,
  sources: CitationSource[],
): ChatAdapter {
  return {
    async sendMessage({ signal }) {
      const timers = new Set<ReturnType<typeof setTimeout>>();
      let close: (() => void) | undefined;
      const clear = () => {
        timers.forEach(clearTimeout);
        timers.clear();
        signal.removeEventListener('abort', abort);
      };
      const abort = () => {
        clear();
        close?.();
        close = undefined;
      };
      return new ReadableStream<ChatChunk>({
        start(controller) {
          close = () => controller.close();
          if (signal.aborted) {
            abort();
            return;
          }
          signal.addEventListener('abort', abort, { once: true });
          const later = (chunk: ChatChunk, ms: number) => {
            const timer = setTimeout(() => {
              timers.delete(timer);
              controller.enqueue(chunk);
              if (chunk.type === 'finish') {
                clear();
                close?.();
                close = undefined;
              }
            }, ms);
            timers.add(timer);
          };
          controller.enqueue({ type: 'start' });
          controller.enqueue({
            type: 'tool-input-available',
            toolCallId: 'scripted-tool',
            toolName: tool.name,
            input: tool.args,
          });
          later({ type: 'tool-output-available', toolCallId: 'scripted-tool', output: tool.result }, tool.durationMs);
          const pieces = chunkReply(reply);
          pieces.forEach((delta, i) =>
            later({ type: 'text-delta', id: 'reply', delta }, tool.durationMs + (i + 1) * tickMs),
          );
          const end = tool.durationMs + (pieces.length + 1) * tickMs;
          sources.forEach((source, i) =>
            later({ type: 'source-url', sourceId: String(i), title: source.title, url: source.url ?? '' }, end),
          );
          later({ type: 'finish' }, end);
        },
        cancel() {
          clear();
          close = undefined;
        },
      });
    },
  };
}

import { ChartLocaleProvider } from '@gntik-ai/charts';
import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import {
  SidebarLayout,
  useI18n,
  type BreadcrumbItem,
  type NavGroup,
  type SidebarLayoutProps,
  type UserMenuUser,
  type Workspace,
} from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends
    Omit<AppSidebarHeaderProps, 'collapsed' | 'className' | 'workspaces'>,
    Pick<
      AppSidebarFooterProps,
      'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'userMenuChildren' | 'onSignOut'
    >,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  userMenuChildren,
  brand,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
  ...contextProps
}: ConsoleShellProps) {
  const { locale } = useI18n();
  return (
    <ChartLocaleProvider locale={locale}>
      <SidebarLayout
        fullScreen
        storageKey={storageKey}
        sidebarLabel={sidebarLabel}
        collapseMode={collapseMode}
        sidebarHeader={({ collapsed }) => (
          <AppSidebarHeader
            collapsed={collapsed}
            workspaces={workspaces}
            currentWorkspaceId={currentWorkspaceId}
            onWorkspaceChange={onWorkspaceChange}
            onCreateWorkspace={onCreateWorkspace}
            brand={brand}
            {...contextProps}
          />
        )}
        sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
        sidebarFooter={({ collapsed }) => (
          <AppSidebarFooter
            collapsed={collapsed}
            user={user}
            usage={usage}
            helpHref={helpHref}
            helpLabel={helpLabel}
            userMenuItems={userMenuItems}
            userMenuChildren={userMenuChildren}
            onSignOut={onSignOut}
          />
        )}
        topbar={
          brand == null ? (
            <AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />
          ) : (
            <>
              <div className="min-w-0 shrink-0 lg:hidden">{brand}</div>
              <AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />
            </>
          )
        }
      >
        {children}
      </SidebarLayout>
    </ChartLocaleProvider>
  );
}
